contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // accept refunds/winnings from C
    receive() external payable {}

    // single public test function: take sendAmount as input and attempt to call play
    // We cannot read C.TICKET_AMOUNT via the interface, so encode the known constant 10 here as ticketPrice.
    function run(uint sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendAmount)); require(sendAmount <= 1000000000000000000000000000000);
        // must be able to fund the attempted payment
        require(address(this).balance >= sendAmount);

        // observe before-values
        address bankBefore = c.bank(); if (__ESBMC_reverted()) return;
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;

        bool reverted;
        // call play with the supplied amount
        c.play{value: sendAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-values
        address bankAfter = c.bank(); if (__ESBMC_reverted()) return;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;

        // Known ticket price constant in contract C is 10. Express rule for that value.
        uint ticketPrice = 10;

        // General rule asserted as a single assert: when sendAmount == ticketPrice,
        // the call must not revert, bank must be unchanged, and potAfter is either potBefore + ticketPrice or 0.
        assert((sendAmount != ticketPrice) || (reverted == false && bankAfter == bankBefore && (potAfter == potBefore + ticketPrice || potAfter == 0)));
    }
}

