// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 sendAmount) internal {
        sendAmount = bound(sendAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        address bankBefore;
        try c.bank() returns (address __r) { bankBefore = __r; } catch { return; }
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        bool reverted;
        try c.play{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        address bankAfter;
        try c.bank() returns (address __r) { bankAfter = __r; } catch { return; }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        uint ticketPrice = 10;
        assertTrue((sendAmount != ticketPrice) || (reverted == false && bankAfter == bankBefore && (potAfter == potBefore + ticketPrice || potAfter == 0)));
    }

    function testFuzz_run(uint256 sendAmount) public {
        _run(sendAmount);
    }

    receive() external payable {}
}
